constexpr int SIDE=729, N=SIDE*SIDE, TC=(SIDE+7)/8, TR=(SIDE+15)/16, TILES=TC*TR;
struct Entry{uint32_t bits;int target;};static_assert(sizeof(Entry)==8,"observer ABI");
__constant__ float labels[27];
__device__ __forceinline__ int logical(uchar2 a,uchar2 b){int out=0;for(int j=0;j<3;j++){out+=((a.x%3-1)*(b.x%3-1)+(a.y%3-1)*(b.y%3-1)+2)*(j==0?1:j==1?5:25);a.x/=3;a.y/=3;b.x/=3;b.y/=3;}return out;}
__device__ __forceinline__ int join(int a,int b){int out=0;for(int j=0;j<3;j++){out+=(a%3+b%3)*(j==0?1:j==1?5:25);a/=3;b/=3;}return out;}
__device__ __forceinline__ uint32_t tf(float x){uint32_t y;asm("cvt.rna.tf32.f32 %0,%1;":"=r"(y):"f"(x));return y;}
__device__ __forceinline__ int observe(float x,const Entry*d,int size){uint32_t bits=__float_as_uint(__uint_as_float(tf(x*0.125f))*0x1p-30f);int lo=0,hi=size;while(lo<hi){int mid=(lo+hi)/2;if(d[mid].bits<bits)lo=mid+1;else hi=mid;}return lo<size&&d[lo].bits==bits?d[lo].target:-1;}
__device__ __forceinline__ void tensor(uint32_t a,uint32_t aa,uint32_t b,float*d){asm volatile("mma.sync.aligned.m16n8k8.row.col.f32.tf32.tf32.f32 {%0,%1,%2,%3}, {%4,%5,%4,%5}, {%6,%6}, {%0,%1,%2,%3};":"+f"(d[0]),"+f"(d[1]),"+f"(d[2]),"+f"(d[3]):"r"(a),"r"(aa),"r"(b));}
