#pragma unroll
for(int s=0;s<4;s++){int ri=rb+g+(s/2)*8,ci=cb+t*2+s%2;if(ri<SIDE&&ci<SIDE){int ta=observe(a[s],dict,count),tb=observe(b[s],dict,count);int got=(ta<0||tb<0)?-1:join(ta,tb);out[ri*SIDE+ci]=got;if(Validate){if(got<0)atomicAdd(bad,1ULL);else if(got!=logical(rows[ri],cols[ci]))atomicAdd(bad+1,1ULL);}}}}
__global__ void direct(const uchar2*rows,const uchar2*cols,int*out){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<N)out[i]=logical(rows[i/SIDE],cols[i%SIDE]);}
__global__ void compare(const int*a,const int*b,unsigned long long*bad){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<N&&a[i]!=b[i])atomicAdd(bad+1,1ULL);}
