float vals[27];int primes[]={2,5,7};for(int i=0;i<27;i++){int n=i;double v=1;for(int j=2;j>=0;j--){int x=n%3;n/=3;v*=pow(double(primes[j]),x==2?0:x==0?1:5);}vals[i]=float(ldexp(v,-15));}CK(cudaMemcpyToSymbol(labels,vals,108));
std::vector<uchar2>h[2];for(int side=0;side<2;side++){h[side].resize(SIDE);for(int i=0;i<SIDE;i++){int x=(i*(side?131:127)+(side?43:17))%SIDE;h[side][i]=make_uchar2(x/27,x%27);}}
