native<true><<<nb,256>>>(r,c,out,dd,d.size(),bad);direct<<<db,256>>>(r,c,ref);CK(cudaGetLastError());CK(cudaDeviceSynchronize());unsigned long long cnt[2];CK(cudaMemcpy(cnt,bad,16,cudaMemcpyDeviceToHost));if(cnt[0]||cnt[1]){printf("{\"status\":\"native_validation_error\",\"missing\":%llu,\"mismatches\":%llu}\n",cnt[0],cnt[1]);return 2;}
native<false><<<nb,256>>>(r,c,out,dd,d.size(),bad);compare<<<db,256>>>(out,ref,bad);CK(cudaGetLastError());CK(cudaDeviceSynchronize());CK(cudaMemcpy(cnt,bad,16,cudaMemcpyDeviceToHost));if(cnt[1]){fprintf(stderr,"timed_native_mismatch\n");return 2;}
for(int i=0;i<5;i++){native<false><<<nb,256>>>(r,c,out,dd,d.size(),bad);direct<<<db,256>>>(r,c,ref);}CK(cudaDeviceSynchronize());cudaEvent_t s,e;CK(cudaEventCreate(&s));CK(cudaEventCreate(&e));std::vector<float>time[2];for(int round=0;round<7;round++)for(int k=0;k<2;k++){int route=(round+k)%2;CK(cudaEventRecord(s));for(int i=0;i<10;i++){if(route==0)native<false><<<nb,256>>>(r,c,out,dd,d.size(),bad);else direct<<<db,256>>>(r,c,ref);}CK(cudaGetLastError());CK(cudaEventRecord(e));CK(cudaEventSynchronize(e));float ms;CK(cudaEventElapsedTime(&ms,s,e));time[route].push_back(ms/10);}
cudaFuncAttributes a,b;CK(cudaFuncGetAttributes(&a,native<false>));CK(cudaFuncGetAttributes(&b,direct));cudaDeviceProp prop;CK(cudaGetDeviceProperties(&prop,0));printf("{\"status\":\"pass\",\"device\":\"%s\",\"cases\":%d,\"distinct_outputs_per_full_tile\":128,\"mma_per_tile\":2,\"missing\":%llu,\"mismatches\":%llu,\"dictionary_bytes\":%ld,\"labels_bytes\":108,\"input_bytes\":%d,\"output_bytes\":%d,\"timings_ms\":{",prop.name,N,cnt[0],cnt[1],bytes,SIDE*4,N*4);const char*names[]={"native_tile_joint_observer","lane_direct"};for(int i=0;i<2;i++){std::sort(time[i].begin(),time[i].end());printf("%s\"%s\":{\"median\":%.6f,\"min\":%.6f,\"max\":%.6f}",i?",":"",names[i],time[i][3],time[i][0],time[i][6]);}printf("},\"registers\":[%d,%d],\"local_bytes_per_thread\":[%zu,%zu],\"shared_bytes_per_block\":[%zu,%zu],\"scope\":\"all 27^4 ternary source tuples as shuffled 729x729 Cartesian pair matrix; 128 independent output cells per full tile; two TF32 MMAs with uniform K replication in each pair, 1/8 normalization, RNA padding, two immutable observer lookups and final three-component dot-sum join; all producers and output included; no single-MMA K compression/model/HTTP claim\"}\n",a.numRegs,b.numRegs,a.localSizeBytes,b.localSizeBytes,a.sharedSizeBytes,b.sharedSizeBytes);
